  Widget _buildContactItem({
    required String name,
    required String phone,
    required String tag,
    required VoidCallback onEdit,
    required VoidCallback onDelete,
  }) {
    IconData icon;
    Color bgColor;
    Color iconColor;

    switch (tag) {
      case '가족':
        icon = Icons.family_restroom;
        bgColor = const Color(0xFFFEE2E2);
        iconColor = const Color(0xFFDC2626);
        break;
      case '친구':
        icon = Icons.people;
        bgColor = const Color(0xFFD1FAE5);
        iconColor = const Color(0xFF16A34A);
        break;
      case '상담사':
        icon = Icons.support_agent;
        bgColor = const Color(0xFFFEF3C7);
        iconColor = const Color(0xFFD97706);
        break;
      default:
        icon = Icons.person;
        bgColor = const Color(0xFFE0E7FF);
        iconColor = const Color(0xFF4338CA);
    }

    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8.0),
      child: Row(
        children: [
          CircleAvatar(
            radius: 20,
            backgroundColor: bgColor,
            child: Icon(icon, color: iconColor, size: 20),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(name, style: const TextStyle(fontWeight: FontWeight.w600)),
                Text('$phone · $tag', style: const TextStyle(color: kColorTextSubtitle)),
              ],
            ),
          ),
          IconButton(
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(),
            icon: const Icon(Icons.edit, color: kColorTextSubtitle, size: 20),
            onPressed: onEdit,
          ),
          IconButton(
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(),
            icon: const Icon(Icons.delete, color: kColorError, size: 20),
            onPressed: onDelete,
          ),
        ],
      ),
    );
  }

  Widget _buildSwitchItem(String title, bool value, Function(bool) onChanged) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8.0),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(title, style: const TextStyle(fontSize: 16)),
          Switch(
            value: value,
            onChanged: onChanged,
            activeThumbColor: kColorBtnPrimary,
            inactiveTrackColor: kColorMoodSliderInactive,
          ),
        ],
      ),
    );
  }

  Widget _buildMenuItem({
    required IconData icon,
    required Color iconColor,
    required String text,
    required VoidCallback onTap,
  }) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(8.0),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 12.0),
        child: Row(
          children: [
