  /// 특정 시간 범위의 평균 심박수 가져오기 (3단계 폴백)
  /// 1단계: Health Connect
  /// 2단계: Samsung Health SDK
  /// 3단계: 심박수 기반 HRV 추정
  Future<Map<String, dynamic>> fetchAverageHeartData({
    required DateTime startTime,
    required DateTime endTime,
  }) async {
    try {
      // 🔵 1단계: Health Connect에서 데이터 가져오기
      List<health.HealthDataPoint> heartData = await _healthFactory
          .getHealthDataFromTypes(
        types: [health.HealthDataType.HEART_RATE],
        startTime: startTime,
        endTime: endTime,
      );

      // Health Connect에 데이터가 없으면 Samsung Health 시도
      if (heartData.isEmpty && Platform.isAndroid) {
        print('🟡 Health Connect에 데이터 없음, Samsung Health 시도...');

        // 🟠 2단계: Samsung Health SDK에서 데이터 가져오기
        if (!_samsungHealthAvailable) {
          await checkSamsungHealthAvailable();
        }

        if (_samsungHealthAvailable && !_samsungHealthInitialized) {
          await initializeSamsungHealth();
        }

        if (_samsungHealthInitialized) {
          final samsungHeartData = await getSamsungHealthHeartRate(
            startTime: startTime,
            endTime: endTime,
          );

          if (samsungHeartData.isNotEmpty) {
            // Samsung Health 데이터로 평균 계산
            int totalHR = 0;
            for (var data in samsungHeartData) {
              totalHR += (data['heartRate'] as num).round();
            }

            final avgHR = (totalHR / samsungHeartData.length).round();
            final avgHRV = estimateHRVFromHeartRate(avgHR, null);

            print('✅ Samsung Health에서 데이터 획득: 평균 심박수 $avgHR, HRV $avgHRV (추정) (${samsungHeartData.length}개 데이터)');

            return {
              'avgHR': avgHR,
              'avgHRV': avgHRV,
              'count': samsungHeartData.length,
              'source': 'samsung_health',
            };
          }
        }

        // Samsung Health도 실패한 경우
        print('⚠️ Samsung Health에서도 데이터 없음');
        return {'avgHR': null, 'avgHRV': null, 'count': 0};
      }

      if (heartData.isEmpty) {
        print('시간대 ${startTime.hour}:00-${endTime.hour}:00 데이터 없음');
        return {'avgHR': null, 'avgHRV': null, 'count': 0};
      }

      // 중복 제거
      final uniqueData = <String, health.HealthDataPoint>{};
      for (var point in heartData) {
        uniqueData[point.uuid] = point;
      }
      heartData = uniqueData.values.toList();

      // 평균 심박수 계산
      int totalHR = 0;
      int count = 0;

      for (var point in heartData) {
        final value = point.value;
        if (value is health.NumericHealthValue) {
          totalHR += value.numericValue.round();
          count++;
        }
      }

      final avgHR = count > 0 ? (totalHR / count).round() : null;

      // 🟢 3단계: 심박수 기반 HRV 추정 (항상 실행)
      final avgHRV = avgHR != null ? estimateHRVFromHeartRate(avgHR, null) : 35;

      print('✅ Health Connect에서 데이터 획득: 평균 심박수 $avgHR, HRV $avgHRV (추정) (${count}개 데이터)');

      return {
        'avgHR': avgHR,
        'avgHRV': avgHRV,
        'count': count,
        'source': 'health_connect',
      };
    } catch (e) {
      print('❌ 평균 심박 데이터 가져오기 실패: $e');

      // 🟠 2단계: Samsung Health SDK 시도
      if (Platform.isAndroid) {
        try {
          if (!_samsungHealthAvailable) {
            await checkSamsungHealthAvailable();
          }

          if (_samsungHealthAvailable && !_samsungHealthInitialized) {
            await initializeSamsungHealth();
          }

          if (_samsungHealthInitialized) {
            final samsungHeartData = await getSamsungHealthHeartRate(
              startTime: startTime,
              endTime: endTime,
            );

            if (samsungHeartData.isNotEmpty) {
              int totalHR = 0;
              for (var data in samsungHeartData) {
                totalHR += (data['heartRate'] as num).round();
              }

              final avgHR = (totalHR / samsungHeartData.length).round();
              final avgHRV = estimateHRVFromHeartRate(avgHR, null);

              print('✅ Samsung Health 폴백 성공: 평균 심박수 $avgHR, HRV $avgHRV (${samsungHeartData.length}개 데이터)');

              return {
                'avgHR': avgHR,
                'avgHRV': avgHRV,
                'count': samsungHeartData.length,
                'source': 'samsung_health_fallback',
              };
            }
          }
        } catch (samsungError) {
          print('❌ Samsung Health 폴백 실패: $samsungError');
        }
      }

      return {'avgHR': null, 'avgHRV': null, 'count': 0};
    }
  }

  /// Health 데이터 처리
  Map<String, dynamic> _processHealthData(
      List<health.HealthDataPoint> healthData, DateTime now) {
    int steps = 0;
    double activeCalories = 0;
    int? currentHR; // null = 데이터 없음
    int? currentHRV; // null = 데이터 없음
    int? restingHR; // null = 데이터 없음

    bool hasSteps = false;
    bool hasCalories = false;
    bool hasHeartRate = false;

    for (var point in healthData) {
      final value = point.value;
      if (value is health.NumericHealthValue) {
        switch (point.type) {
          case health.HealthDataType.STEPS:
            steps += value.numericValue.round();
            hasSteps = true;
            break;
          case health.HealthDataType.ACTIVE_ENERGY_BURNED:
            activeCalories += value.numericValue;
            hasCalories = true;
            break;
          case health.HealthDataType.HEART_RATE:
          // 가장 최근 심박수 사용
            if (point.dateTo.isAfter(
                now.subtract(const Duration(minutes: 10)))) {
              currentHR = value.numericValue.round();
              hasHeartRate = true;
            }
            break;
          case health.HealthDataType.HEART_RATE_VARIABILITY_SDNN:
          case health.HealthDataType.HEART_RATE_VARIABILITY_RMSSD: // 🆕 RMSSD 추가
          // 가장 최근 HRV 사용 (SDNN 또는 RMSSD)
            if (point.dateTo.isAfter(
                now.subtract(const Duration(minutes: 10)))) {
              currentHRV = value.numericValue.round();
              print('HRV 발견: $currentHRV ms (${point.type})');
            }
            break;
          case health.HealthDataType.RESTING_HEART_RATE:
            restingHR = value.numericValue.round();
            break;
          default:
            break;
        }
      }
    }

    // HRV가 없으면 심박수 기반으로 추정
    if (currentHR != null && currentHRV == null) {
      currentHRV = estimateHRVFromHeartRate(currentHR, restingHR);
      print('HRV를 심박수 기반으로 추정: $currentHRV ms');
    }

    print('처리된 데이터: 걸음수=$steps (데이터 있음: $hasSteps), '
        '칼로리=$activeCalories (데이터 있음: $hasCalories), '
        '심박수=$currentHR (데이터 있음: $hasHeartRate), '
        'HRV=$currentHRV ${currentHRV != null ? '(추정)' : ''}');

    return {
      'steps': steps,
      'activeCalories': activeCalories,
      'currentHR': currentHR,
      'currentHRV': currentHRV,
      'restingHR': restingHR,
      'timestamp': now,
    };
  }

  /// 시간별로 데이터 그룹화 및 평균 계산
  List<Map<String, dynamic>> _groupDataByHour(
      List<health.HealthDataPoint> data, DateTime startDate) {
    List<Map<String, dynamic>> hourlyData = [];

    // 2시간 간격으로 데이터 그룹화 (06:00-08:00, 08:00-10:00, ...)
    for (int hour = 6; hour < 22; hour += 2) {
      final timeSlotStart = DateTime(
          startDate.year, startDate.month, startDate.day, hour);
      final timeSlotEnd = timeSlotStart.add(const Duration(hours: 2));

      // 해당 시간대의 데이터 필터링
      final timeSlotData = data.where((point) =>
      point.dateFrom.isAfter(timeSlotStart) &&
          point.dateFrom.isBefore(timeSlotEnd));

      if (timeSlotData.isEmpty) {
        print('⚠️ ${hour}:00-${hour + 2}:00 시간대: 데이터 없음');
        continue;
      }

      // 해당 시간대의 평균 심박수 계산
      int hrSum = 0;
      int hrCount = 0;
      int hrvSum = 0;
      int hrvCount = 0;

      for (var point in timeSlotData) {
        final value = point.value;
        if (value is health.NumericHealthValue) {
          if (point.type == health.HealthDataType.HEART_RATE) {
            hrSum += value.numericValue.round();
            hrCount++;
          } else if (point.type == health.HealthDataType.HEART_RATE_VARIABILITY_SDNN ||
              point.type == health.HealthDataType.HEART_RATE_VARIABILITY_RMSSD) { // 🆕 RMSSD 추가
            hrvSum += value.numericValue.round();
            hrvCount++;
            print('HRV 데이터 발견: ${value.numericValue.round()} ms (${point.type})');
          }
        }
      }

      // 심박수 데이터만 있어도 스트레스 로그 추가 (HRV는 옵션)
      if (hrCount > 0) {
        final avgHR = hrSum ~/ hrCount;

        // HRV가 없으면 심박수 기반으로 추정
        final avgHRV = hrvCount > 0
            ? hrvSum ~/ hrvCount  // 실제 HRV 데이터 사용
            : estimateHRVFromHeartRate(avgHR, null); // 심박수 기반 추정 🆕

        final stress = calculateStressLevel(avgHR, avgHRV);

        print('✅ ${hour}:00-${hour + 2}:00 시간대: 평균 심박수 $avgHR BPM, HRV $avgHRV ms ${hrvCount > 0 ? '(실제)' : '(추정)'} (${hrCount}개 데이터)');

        hourlyData.add({
          'time': '${hour.toString().padLeft(2, '0')}:00',
          'hr': avgHR,
          'hrv': avgHRV,
          'stress': stress,
          'dataCount': hrCount, // 데이터 개수 추가
        });
      }
    }

    print('📊 그룹화된 시간별 데이터: ${hourlyData.length}개 시간대 (총 ${data.length}개 데이터 포인트)');
    return hourlyData;
  }

  /// 심박수 기반 HRV 추정
  /// Samsung Health가 없을 때 심박수를 기반으로 HRV를 추정
  /// 완벽하지 않지만 고정값보다는 나음
  int estimateHRVFromHeartRate(int heartRate, int? restingHR) {
    final restingHeartRate = restingHR ?? 60;

    // 안정 시 심박수 대비 현재 심박수 비율
    final hrRatio = heartRate / restingHeartRate;

    // 심박수가 높을수록 HRV는 낮아지는 경향
    // 과학적 근거: 교감신경 활성화 시 HR↑, HRV↓
    if (hrRatio <= 1.0) {
      // 안정 상태 또는 그 이하 → 높은 HRV
      return 50 + ((1.0 - hrRatio) * 30).round(); // 50-80ms
    } else if (hrRatio <= 1.15) {
      // 약간 증가 → 중간 HRV
      return 35 + ((1.15 - hrRatio) * 100).round(); // 35-50ms
    } else if (hrRatio <= 1.3) {
      // 중간 정도 증가 → 낮은 HRV
      return 25 + ((1.3 - hrRatio) * 67).round(); // 25-35ms
    } else if (hrRatio <= 1.5) {
      // 많이 증가 → 매우 낮은 HRV
      return 15 + ((1.5 - hrRatio) * 50).round(); // 15-25ms
    } else {
      // 극도로 높음 → 최소 HRV
      return 15; // 15ms
    }
  }

  /// 스트레스 레벨 계산
  /// HR과 HRV를 기반으로 0-100 사이의 스트레스 점수 계산
  int calculateStressLevel(int heartRate, int hrv) {
    // 정규화된 심박수 (안정시 심박수 60, 최대 100 가정)
    double normalizedHR = ((heartRate - 60) / 40).clamp(0.0, 1.0);

    // 정규화된 HRV (높을수록 좋음, 20-80 범위 가정)
    double normalizedHRV = (1 - ((hrv - 20) / 60).clamp(0.0, 1.0));

    // 가중 평균으로 스트레스 점수 계산
    // HR 60%, HRV 40% 가중치
    double stressScore = (normalizedHR * 0.6 + normalizedHRV * 0.4) * 100;

    return stressScore.round().clamp(0, 100);
  }

  /// HRV 기반 생체리듬 점수 계산 (0-100)
  /// HRV RMSSD가 높을수록 건강한 상태 = 높은 점수
  ///
  /// HRV 범위 참고 (성인 기준):
  /// - 20ms 미만: 매우 낮음 (스트레스/피로 상태)
  /// - 20-40ms: 낮음
  /// - 40-60ms: 보통
  /// - 60-80ms: 좋음
  /// - 80ms 이상: 매우 좋음
  int? calculateBiorhythmScoreFromHRV(double? hrvRmssd) {
    if (hrvRmssd == null || hrvRmssd <= 0) {
      print('⚠️ HRV 데이터 없음 - 생체리듬 점수 계산 불가');
      return null; // 데이터 없으면 null 반환
    }

    // HRV를 0-100 점수로 변환
    // 최소 15ms, 최대 100ms 범위로 정규화
    const double minHRV = 15.0;
    const double maxHRV = 100.0;

    double normalizedHRV = ((hrvRmssd - minHRV) / (maxHRV - minHRV)).clamp(0.0, 1.0);

    // 선형 변환으로 점수 계산
    double score = normalizedHRV * 100;

    int finalScore = score.round().clamp(0, 100);

    print('📊 생체리듬 점수 계산: HRV=$hrvRmssd ms → 점수=$finalScore');

    return finalScore;
  }

  /// HR과 HRV를 종합하여 생체리듬 점수 계산
  /// HRV가 있으면 HRV 우선, 없으면 HR 기반 추정
  int? calculateBiorhythmScore({
    int? heartRate,
    double? hrvRmssd,
    int? restingHR,
  }) {
    // 1. HRV 데이터가 있으면 HRV 기반 점수 계산
    if (hrvRmssd != null && hrvRmssd > 0) {
      return calculateBiorhythmScoreFromHRV(hrvRmssd);
    }

    // 2. HRV가 없지만 HR이 있으면, HR 기반 추정 HRV로 계산
    if (heartRate != null) {
      final estimatedHRV = estimateHRVFromHeartRate(heartRate, restingHR);
      print('ℹ️ HRV 없음, 심박수 기반 추정 HRV 사용: $estimatedHRV ms');
      return calculateBiorhythmScoreFromHRV(estimatedHRV.toDouble());
    }

    // 3. 둘 다 없으면 null
    print('⚠️ HR, HRV 데이터 모두 없음 - 생체리듬 점수 계산 불가');
    return null;
  }

  /// 사용자 상태 분석
  Map<String, dynamic> analyzeUserState(int? heartRate, int? hrv, int? restingHR) {
    // 데이터가 없으면 기본 상태 반환
    if (heartRate == null || hrv == null || restingHR == null) {
      return {
        'state': '데이터 수집 중',
        'stressLevel': 0,
        'recommendation': 'Health Connect에 데이터 소스를 연결하고 웨어러블 기기를 동기화하세요.',
      };
    }

    final stressLevel = calculateStressLevel(heartRate, hrv);

    String state;
    String recommendation;

    // HR이 안정시보다 20% 이상 높고, HRV가 낮은 경우
    if (heartRate > restingHR * 1.2 && hrv < 30) {
      state = '높은 스트레스';
      recommendation = '심호흡이나 명상으로 긴장을 풀어보세요. 잠시 휴식이 필요합니다.';
    }
    // HR이 안정시보다 10-20% 높거나 HRV가 중간인 경우
    else if (heartRate > restingHR * 1.1 || hrv < 40) {
      state = '약간 긴장';
      recommendation = '가볍게 스트레칭을 하거나 잠깐 산책해보세요.';
    }
    // HRV가 높고 HR이 안정적인 경우
    else if (hrv > 50 && heartRate < restingHR * 1.1) {
      state = '편안함';
      recommendation = '좋은 컨디션입니다! 현재 상태를 유지하세요.';
    }
    // 그 외
    else {
      state = '보통';
      recommendation = '평온한 상태입니다. 꾸준한 활동을 유지하세요.';
    }

    return {
      'state': state,
      'stressLevel': stressLevel,
      'recommendation': recommendation,
    };
  }

  /// 기본 데이터 반환 (권한 없거나 데이터 없을 때)
  Map<String, dynamic> _getDefaultHealthData() {
    return {
      'steps': 0,
      'activeCalories': 0.0,
      'currentHR': null, // 데이터 없음
      'currentHRV': null, // 데이터 없음
      'restingHR': null, // 데이터 없음
      'timestamp': DateTime.now(),
    };
  }

  /// Firestore에 건강 데이터 저장
  Future<void> saveHealthDataToFirestore(
      String userId, Map<String, dynamic> healthData) async {
    try {
      await FirebaseFirestore.instance
          .collection('users')
          .doc(userId)
          .collection('health_data')
          .add({
        ...healthData,
        'createdAt': FieldValue.serverTimestamp(),
      });
    } catch (e) {
      print('Firestore 저장 실패: $e');
    }
  }

  /// Firestore에서 오늘의 건강 데이터 가져오기
  Future<List<Map<String, dynamic>>> getTodayHealthDataFromFirestore(
      String userId) async {
    try {
      final now = DateTime.now();
      final startOfDay = DateTime(now.year, now.month, now.day);

      final snapshot = await FirebaseFirestore.instance
          .collection('users')
          .doc(userId)
          .collection('health_data')
          .where('timestamp', isGreaterThanOrEqualTo: startOfDay)
          .orderBy('timestamp', descending: false)
          .get();

      return snapshot.docs
          .map((doc) => doc.data() as Map<String, dynamic>)
          .toList();
    } catch (e) {
      print('Firestore에서 데이터 가져오기 실패: $e');
      return [];
    }
  }

  /// 연결된 데이터 소스 및 기기 정보 가져오기
  Future<List<Map<String, dynamic>>> getConnectedDevices() async {
    try {
      final now = DateTime.now();
      final yesterday = now.subtract(const Duration(days: 1));

      // 최근 데이터를 가져와서 소스 확인
      List<health.HealthDataPoint> healthData = await _healthFactory
          .getHealthDataFromTypes(
        types: [health.HealthDataType.STEPS, health.HealthDataType.HEART_RATE],
        startTime: yesterday,
        endTime: now,
      );

      // 기기 정보 추출 (중복 제거)
      Map<String, Map<String, dynamic>> deviceMap = {};

      for (var point in healthData) {
        // 기기 ID를 키로 사용
        final deviceKey = '${point.sourceId}_${point.sourceName}';

        if (!deviceMap.containsKey(deviceKey)) {
          // 기기 정보 구성
          String deviceName = point.sourceName;
          String manufacturer = '';
          String model = '';

          // sourceName에서 기기 정보 추출
          if (point.sourceName.toLowerCase().contains('samsung')) {
            manufacturer = 'Samsung';
            if (point.sourceName.toLowerCase().contains('watch')) {
              deviceName = 'Samsung Galaxy Watch';
            }
          } else if (point.sourceName.toLowerCase().contains('fitbit')) {
            manufacturer = 'Fitbit';
            deviceName = 'Fitbit Device';
          } else if (point.sourceName.toLowerCase().contains('garmin')) {
            manufacturer = 'Garmin';
            deviceName = 'Garmin Device';
          } else if (point.sourceName.toLowerCase().contains('apple')) {
            manufacturer = 'Apple';
            deviceName = 'Apple Watch';
          } else if (point.sourceName.toLowerCase().contains('google fit')) {
            manufacturer = 'Google';
            deviceName = 'Google Fit (연결된 기기)';
          }

          deviceMap[deviceKey] = {
            'name': deviceName.isNotEmpty ? deviceName : point.sourceName,
            'manufacturer': manufacturer,
            'sourceName': point.sourceName,
            'sourceId': point.sourceId,
            'lastSync': point.dateTo,
          };

          print('발견된 기기: $deviceName (${point.sourceName})');
        }
      }

      print('총 ${deviceMap.length}개 기기 발견');
      return deviceMap.values.toList();
    } catch (e) {
      print('기기 정보 가져오기 실패: $e');
      return [];
    }
  }

  // ===== Wear OS HRV Data Integration =====

  /// 워치 앱으로부터 최신 HRV 데이터 가져오기
  ///
  /// Returns: {
  ///   "rmssd": double,
  ///   "avgHeartRate": int,
  ///   "timestamp": int (milliseconds),
  ///   "formattedTime": String
  /// } or null if no data available
  Future<Map<String, dynamic>?> getLatestHrvDataFromWatch() async {
    if (!Platform.isAndroid) {
      print('⚠️ Wear OS HRV는 Android에서만 사용 가능합니다');
      return null;
    }

    try {
      final result = await _samsungHealthChannel.invokeMethod('getLatestHrvData');

      if (result != null && result is Map) {
        final data = Map<String, dynamic>.from(result);
        print('✅ 워치로부터 HRV 데이터 수신:');
        print('   RMSSD: ${data['rmssd']} ms');
        print('   Avg HR: ${data['avgHeartRate']} bpm');
        print('   Time: ${data['formattedTime']}');
        return data;
      } else {
        print('ℹ️ 워치로부터 수신된 HRV 데이터가 없습니다');
        return null;
      }
    } catch (e) {
      print('❌ 워치 HRV 데이터 가져오기 실패: $e');
      return null;
    }
  }

  /// 워치 HRV 데이터를 Firestore에 저장
  ///
  /// [userId] - 사용자 ID
  /// [hrvData] - getLatestHrvDataFromWatch()에서 반환된 데이터
  Future<void> saveWatchHrvToFirestore(String userId, Map<String, dynamic> hrvData) async {
    try {
      final timestamp = DateTime.fromMillisecondsSinceEpoch(hrvData['timestamp'] as int);

      await FirebaseFirestore.instance
          .collection('users')
          .doc(userId)
          .collection('hrv_records')
          .add({
        'rmssd': hrvData['rmssd'],
        'avgHeartRate': hrvData['avgHeartRate'],
        'timestamp': Timestamp.fromDate(timestamp),
        'source': 'wear_os_watch',
        'formattedTime': hrvData['formattedTime'],
      });

      print('✅ 워치 HRV 데이터 Firestore 저장 완료');
    } catch (e) {
      print('❌ 워치 HRV 데이터 저장 실패: $e');
      rethrow;
    }
  }

  /// 워치 HRV 데이터 스트림 (실시간 업데이트)
  ///
  /// 주기적으로 워치로부터 새 데이터를 폴링하고 스트림으로 전달
  Stream<Map<String, dynamic>?> watchHrvDataStream({
    Duration pollInterval = const Duration(seconds: 30),
  }) async* {
    while (true) {
      final data = await getLatestHrvDataFromWatch();
      yield data;
      await Future.delayed(pollInterval);
    }
  }
}

import 'package:flutter/material.dart';
import 'dart:async';
import 'dart:io'; // Platform detection
import 'package:untitled/main_screen.dart'; // Import main_screen.dart to use its color constants
import 'package:untitled/services/health_service.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:untitled/services/firestore_service.dart'; // 이 줄을 추가하세요

// [!!] 1. 새 RTF 파일에서 추가된 색상
const Color kConnectedGreen = Color(0xFF21C45D); // "연결됨"
const Color kStressHigh = Color(0xFFF59E0B); // 스트레스 '높음' (주황)
const Color kStressNormal = Color(0xFF3B81F5); // 스트레스 '보통' (파랑)
const Color kStressLow = Color(0xFF4ADE80); // 스트레스 '낮음' (밝은 녹색)
const Color kPrimaryGreen = Color(0xFF16A34A);


/// 웨어러블 기기 연동 페이지 (웨어러블 기기_수정.rtf 기반)
class WearableDeviceScreen extends StatefulWidget {
  const WearableDeviceScreen({Key? key}) : super(key: key);

  @override
  _WearableDeviceScreenState createState() => _WearableDeviceScreenState();
}

class _WearableDeviceScreenState extends State<WearableDeviceScreen> {
  final HealthService _healthService = HealthService();
  final FirestoreService _firestoreService = FirestoreService();
  final String? _currentUserId = FirebaseAuth.instance.currentUser?.uid;

  Timer? _dataUpdateTimer;
  bool _isLoading = true;
  bool _isConnected = false;

  // 실시간 모니터링 데이터
  int _steps = 0;
  double _activeCalories = 0;
  int? _currentHR; // null = 데이터 없음
  int? _currentHRV; // null = 데이터 없음
  int? _restingHR; // null = 데이터 없음
  int _currentStress = 0;
  String _userState = '데이터 수집 중';
  String _recommendation = '';
  Color _userStateColor = kColorTextHint;

  // 연결된 기기 목록
  List<Map<String, dynamic>> _connectedDevices = [];

  // 스트레스 로그 데이터 (실제 데이터로 채워짐)
  List<Map<String, dynamic>> _stressLog = [];

  @override
  void initState() {
    super.initState();
    _initializeHealthData();
    // 5분마다 데이터 업데이트
    _dataUpdateTimer = Timer.periodic(
      const Duration(minutes: 5),
          (timer) => _refreshHealthData(),
    );
  }

  @override
  void dispose() {
    _dataUpdateTimer?.cancel();
    super.dispose();
  }

  /// Health 데이터 초기화
  /// [주의] MainScreen에서 이미 권한을 요청했으므로 여기서는 확인만 합니다.
  Future<void> _initializeHealthData() async {
    setState(() {
      _isLoading = true;
    });

    try {
      // Android: Health Connect 상태 확인
      if (Platform.isAndroid) {
        final status = await _healthService.checkHealthConnectStatus();
        print('Health Connect SDK 상태: $status');

        if (status.toString().contains('unavailable')) {
          _showErrorSnackBar('Health Connect가 설치되지 않았습니다.\nGoogle Play에서 Health Connect를 설치하세요.');
          return;
        }
      }

      // 권한이 이미 있는지 확인 (MainScreen에서 이미 요청했음)
      print('🔍 Health 권한 확인 중...');
      bool authorized = await _healthService.requestAuthorization();
      print('📋 Health 권한 상태: $authorized');
      // 필요하면 권한 재요청 (사용자가 명시적으로 거부한 경우)
      // authorized = await _healthService.requestAuthorization();

      if (authorized) {
        await _refreshHealthData();
        await _loadTodayStressLog();

        // 연결된 웨어러블 기기 정보 가져오기
        final devices = await _healthService.getConnectedDevices();
        print('가져온 기기 정보: $devices');

        setState(() {
          _isConnected = true;

          // 개발/테스트용: 데이터가 없으면 샘플 데이터 사용
          final bool useTestData = devices.isEmpty && Platform.isAndroid;

          if (useTestData) {
            // 테스트용 샘플 기기 및 데이터 표시
            print('⚠️ 실제 데이터 없음 - 샘플 데이터 사용');
            _connectedDevices = [
              {'name': '샘플 기기 (Health Connect 데이터 없음)', 'battery': null, 'status': '데이터 소스를 연결하세요'},
            ];

            // 샘플 심박수 데이터 생성
            _stressLog = [
              {'time': '06:00', 'hr': 72, 'hrv': 35, 'stress': 30},
              {'time': '08:00', 'hr': 78, 'hrv': 32, 'stress': 40},
              {'time': '10:00', 'hr': 85, 'hrv': 28, 'stress': 55},
              {'time': '12:00', 'hr': 80, 'hrv': 30, 'stress': 45},
              {'time': '14:00', 'hr': 75, 'hrv': 33, 'stress': 35},
            ];
          } else if (devices.isNotEmpty) {
            // 실제 웨어러블 기기가 있으면 표시
            _connectedDevices = devices.map((device) {
              // 마지막 동기화 시간 계산
              final lastSync = device['lastSync'] as DateTime;
              final difference = DateTime.now().difference(lastSync);
              String syncStatus;

              if (difference.inMinutes < 5) {
                syncStatus = '방금 전';
              } else if (difference.inMinutes < 60) {
                syncStatus = '${difference.inMinutes}분 전';
              } else if (difference.inHours < 24) {
                syncStatus = '${difference.inHours}시간 전';
              } else {
                syncStatus = '${difference.inDays}일 전';
              }

              return {
                'name': device['name'] as String,
                'battery': null, // Health API에서 배터리 정보는 제공하지 않음
                'status': syncStatus,
              };
            }).toList();
          } else {
            // 기기가 없으면 플랫폼 기본값 표시
            if (Platform.isIOS) {
              _connectedDevices = [
                {'name': 'Apple Health', 'battery': null, 'status': '데이터 동기화 활성화됨'},
              ];
            } else if (Platform.isAndroid) {
              _connectedDevices = [
                {'name': 'Health Connect', 'battery': null, 'status': '데이터 동기화 활성화됨'},
              ];
            } else {
              _connectedDevices = [
                {'name': 'Health Connect', 'battery': null, 'status': '데이터 동기화 활성화됨'},
              ];
            }
          }
        });
      } else {
        final errorMsg = Platform.isAndroid
            ? 'Health Connect 권한이 필요합니다.\nHealth Connect 앱에서 이 앱의 권한을 확인하세요.'
            : 'Apple Health 데이터 접근 권한이 필요합니다.';
        _showErrorSnackBar(errorMsg);
      }
    } catch (e) {
      _showErrorSnackBar('데이터를 가져오는 중 오류가 발생했습니다: $e');
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

  /// Health 데이터 새로고침
  // [수정] 2시간 간격 평균 HRV 기반으로 생체리듬 점수 계산
  Future<void> _refreshHealthData() async {
    try {
      final now = DateTime.now();

      // 1. HealthService에서 실시간 데이터 가져오기
      final healthData = await _healthService.fetchRecentHealthData();
      final oneHourAgo = now.subtract(const Duration(hours: 1));
      final avgHeartData = await _healthService.fetchAverageHeartData(
        startTime: oneHourAgo,
        endTime: now,
      );

      setState(() {
        _steps = healthData['steps'] ?? 0;
        _activeCalories = healthData['activeCalories'] ?? 0.0;
        _currentHR = avgHeartData['avgHR'];
        _currentHRV = avgHeartData['avgHRV'];
        _restingHR = healthData['restingHR'];
      });

      // 2. 사용자 상태 및 스트레스 분석 (UI 표시용)
      _analyzeUserState();

      // 3. 2시간 간격 데이터 로드 (평균 HRV 계산용)
      await _loadTodayStressLog();

      // 4. [핵심] 2시간 간격 평균 HRV 기반으로 생체리듬 점수 계산 및 저장
      final userId = _currentUserId;
      if (userId != null) {
        // A. 기존 방식의 로그 저장 (선택 사항 - 실시간 데이터 기록)
        await _healthService.saveHealthDataToFirestore(userId, {
          'steps': _steps,
          'activeCalories': _activeCalories,
          'heartRate': _currentHR,
          'hrv': _currentHRV,
          'restingHR': _restingHR,
          'stressLevel': _currentStress,
          'userState': _userState,
          'timestamp': now,
        });

        // B. [수정] 2시간 간격 평균 HRV로 생체리듬 점수 계산
        final avgHrvData = _calculateAverageHrvFromStressLog();
        final double? avgHrv = avgHrvData['avgHrv'];
        final double? avgHrDouble = avgHrvData['avgHr'];
        final int? avgHr = avgHrDouble?.round();  // double을 int로 변환

        if (avgHrv != null && avgHrv > 0) {
          // HRV 기반 생체리듬 점수 계산
          final int? biorhythmScore = _healthService.calculateBiorhythmScoreFromHRV(avgHrv);

          if (biorhythmScore != null) {
            // 새로운 updateBiometricScore 사용
            await _firestoreService.updateBiometricScore(
              userId,
              biorhythmScore: biorhythmScore,
              hrvValue: avgHrv,
              heartRate: avgHr,
            );

            print('✅ [Wearable] 생체리듬 점수 업데이트 완료:');
            print('   📊 2시간 간격 평균 HRV: ${avgHrv.toStringAsFixed(1)} ms');
            print('   📊 2시간 간격 평균 HR: $avgHr bpm');
            print('   🏆 생체리듬 점수: $biorhythmScore / 100');
          } else {
            print('⚠️ [Wearable] 생체리듬 점수 계산 실패 - HRV 값 유효하지 않음');
          }
        } else {
          print('⚠️ [Wearable] 2시간 간격 HRV 데이터 없음 - 생체리듬 점수 저장 건너뜀');
        }
      }
    } catch (e) {
      print('데이터 새로고침 실패: $e');
    }
  }

  /// 2시간 간격 스트레스 로그에서 평균 HRV와 HR 계산
  Map<String, double?> _calculateAverageHrvFromStressLog() {
    if (_stressLog.isEmpty) {
      return {'avgHrv': null, 'avgHr': null};
    }

    double totalHrv = 0;
    double totalHr = 0;
    int hrvCount = 0;
    int hrCount = 0;

    for (var log in _stressLog) {
      // HRV 값 추출
      final hrv = log['hrv'];
      if (hrv != null && hrv is num && hrv > 0) {
        totalHrv += hrv.toDouble();
        hrvCount++;
      }

      // HR 값 추출
      final hr = log['hr'];
      if (hr != null && hr is num && hr > 0) {
        totalHr += hr.toDouble();
        hrCount++;
      }
    }

    final double? avgHrv = hrvCount > 0 ? totalHrv / hrvCount : null;
    final double? avgHr = hrCount > 0 ? totalHr / hrCount : null;

    print('📈 [StressLog 분석] 총 ${_stressLog.length}개 기록');
    print('   평균 HRV: ${avgHrv?.toStringAsFixed(1) ?? "없음"} ms (${hrvCount}개 데이터)');
    print('   평균 HR: ${avgHr?.toStringAsFixed(1) ?? "없음"} bpm (${hrCount}개 데이터)');

    return {
      'avgHrv': avgHrv,
      'avgHr': avgHr,
    };
  }

