    /**
     * Samsung Health Data SDK 초기화 및 권한 요청
     */
    private fun initializeSamsungHealth(result: MethodChannel.Result) {
        if (!samsungHealthAvailable || healthDataStore == null) {
            println("⚠️ Samsung Health SDK를 사용할 수 없음")
            result.success(false)
            return
        }

        CoroutineScope(Dispatchers.IO).launch {
            try {
                println("🔐 Samsung Health 권한 요청 시작...")

                // Permission 클래스 (올바른 패키지 경로 사용)
                val permissionClass = Class.forName("com.samsung.android.sdk.health.data.permission.Permission")
                Class.forName("com.samsung.android.sdk.health.data.request.DataType")
                val accessTypeClass = Class.forName("com.samsung.android.sdk.health.data.permission.AccessType")

                // DataType.HeartRateType 가져오기
                val heartRateTypeClass = Class.forName("com.samsung.android.sdk.health.data.request.DataType\$HeartRateType")
                val heartRateTypeCompanion = heartRateTypeClass.getField("Companion").get(null)
                val heartRateDataType = heartRateTypeCompanion

                // AccessType.READ 가져오기
                val accessTypeReadField = accessTypeClass.getField("READ")
                val accessTypeRead = accessTypeReadField.get(null)

                // Permission.of(DataType.HeartRateType, AccessType.READ) 생성
                val permissionOfMethod = permissionClass.getMethod(
                    "of",
                    Class.forName("com.samsung.android.sdk.health.data.request.DataType"),
                    accessTypeClass
                )
                val heartRatePermission = permissionOfMethod.invoke(null, heartRateDataType, accessTypeRead)

                val permissions = setOf(heartRatePermission)
                println("✅ 권한 객체 생성 완료: $permissions")

                // requestPermissionsAsync 호출 (메인 스레드에서 실행)
                withContext(Dispatchers.Main) {
                    try {
                        val requestPermissionsMethod = healthDataStore!!.javaClass.getMethod(
                            "requestPermissionsAsync",
                            Set::class.java,
                            android.app.Activity::class.java
                        )
                        println("🚀 권한 요청 중...")
                        requestPermissionsMethod.invoke(healthDataStore, permissions, this@MainActivity)

                        println("✅ Samsung Health 권한 요청 완료")
                        result.success(true)
                    } catch (e: Exception) {
                        println("❌ 권한 요청 실패: ${e.message}")
                        e.printStackTrace()
                        result.error("PERMISSION_REQUEST_FAILED", e.message, null)
                    }
                }
            } catch (e: ClassNotFoundException) {
                println("❌ Samsung Health SDK 클래스를 찾을 수 없음")
                println("   상세: ${e.message}")
                e.printStackTrace()
                withContext(Dispatchers.Main) {
                    result.error("SDK_NOT_FOUND", "Samsung Health SDK 클래스를 찾을 수 없습니다", null)
                }
            } catch (e: Exception) {
                println("❌ Samsung Health 초기화 실패: ${e.message}")
                e.printStackTrace()
                withContext(Dispatchers.Main) {
                    result.error("INITIALIZATION_FAILED", e.message, null)
                }
            }
        }
    }

    /**
     * Samsung Health에서 심박수 데이터 가져오기
     */
    private fun getHeartRateData(startTimeMillis: Long, endTimeMillis: Long, result: MethodChannel.Result) {
        if (!samsungHealthAvailable || healthDataStore == null) {
            result.error("NOT_INITIALIZED", "Samsung Health가 초기화되지 않았습니다", null)
            return
        }

        CoroutineScope(Dispatchers.IO).launch {
            try {
                // 리플렉션을 사용하여 데이터 가져오기
                println("⚠️ Samsung Health 데이터 가져오기는 AAR 파일이 필요합니다")
                withContext(Dispatchers.Main) {
                    result.success(emptyList<Map<String, Any>>())
                }
            } catch (e: Exception) {
                println("❌ Samsung Health 데이터 읽기 실패: ${e.message}")
                withContext(Dispatchers.Main) {
                    result.error("READ_FAILED", e.message, null)
                }
            }
        }
    }
}

package com.project.personaltherapy

import android.content.Context
import android.util.Log
import androidx.health.connect.client.HealthConnectClient
import androidx.health.connect.client.records.HeartRateVariabilityRmssdRecord
import androidx.health.connect.client.records.metadata.Metadata
import androidx.health.connect.client.records.metadata.DataOrigin
import com.google.android.gms.wearable.DataEvent
import com.google.android.gms.wearable.DataEventBuffer
import com.google.android.gms.wearable.DataMapItem
import com.google.android.gms.wearable.WearableListenerService
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import java.time.Instant
import java.time.ZoneOffset

class WearDataListenerService : WearableListenerService() {

    companion object {
        private const val TAG = "WearDataListener"
    }

    override fun onDataChanged(dataEvents: DataEventBuffer) {
        // 헬스 커넥트 클라이언트 생성 (Context 필요)
        val healthConnectClient = HealthConnectClient.getOrCreate(applicationContext)

        for (event in dataEvents) {
            if (event.type == DataEvent.TYPE_CHANGED) {
                val item = event.dataItem
                if (item.uri.path == "/hrv_data") {
                    val dataMap = DataMapItem.fromDataItem(item).dataMap

                    val rmssd = dataMap.getDouble("rmssd")
                    val timestamp = dataMap.getLong("timestamp")

                    Log.d(TAG, "⌚ 워치 데이터 수신: RMSSD=$rmssd, Time=$timestamp")

                    // ✅ 헬스 커넥트에 저장 (비동기 실행)
                    saveToHealthConnect(healthConnectClient, rmssd, timestamp)
                }
            }
        }
    }

    private fun saveToHealthConnect(client: HealthConnectClient, rmssd: Double, timestamp: Long) {
        CoroutineScope(Dispatchers.IO).launch {
            try {
                // 1. 기록 객체 생성
                val record = HeartRateVariabilityRmssdRecord(
                    time = Instant.ofEpochMilli(timestamp),
                    zoneOffset = ZoneOffset.systemDefault().rules.getOffset(Instant.now()),
                    heartRateVariabilityMillis = rmssd,
                    // ✅ 정답: 생성자 대신 manualEntry() 사용
                    metadata = androidx.health.connect.client.records.metadata.Metadata.manualEntry()
                )

                // 2. 헬스 커넥트에 쓰기 (Insert)
                client.insertRecords(listOf(record))

                Log.d(TAG, "✅ 헬스 커넥트 저장 완료! (RMSSD: $rmssd)")

            } catch (e: Exception) {
                // 권한이 없거나, 다른 이유로 실패했을 때
                Log.e(TAG, "❌ 헬스 커넥트 저장 실패: ${e.message}")
                // 실패 원인이 '권한 없음'이라면 사용자에게 앱을 켜달라고 알림을 띄우는 것도 방법
            }
        }
    }
}

package com.project.personaltherapy

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Intent
import androidx.core.app.NotificationCompat
import androidx.health.services.client.HealthServices
import androidx.health.services.client.MeasureCallback
import androidx.health.services.client.data.Availability
import androidx.health.services.client.data.DataPointContainer
import androidx.health.services.client.data.DataType
import androidx.health.services.client.data.DeltaDataType
import androidx.lifecycle.LifecycleService
import androidx.lifecycle.lifecycleScope
import com.google.android.gms.tasks.Tasks
import com.google.android.gms.wearable.PutDataMapRequest
import com.google.android.gms.wearable.Wearable
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import kotlin.math.pow
import kotlin.math.sqrt

/**
 * Galaxy Watch에서 Health Services API를 사용하여 HRV를 측정하는 서비스
 *
 * Health Services는 Galaxy Watch에서 고품질 심박 데이터를 제공합니다.
 * IBI (Inter-Beat Interval) 데이터를 포함하여 정확한 HRV 계산이 가능합니다.
 */
class HrvMonitorService : LifecycleService() {

    private val rrIntervals = mutableListOf<Double>() // RR Interval (ms) 저장용
    private var isRunning = false
    private var isMeasuring = false

    private var measureClient: androidx.health.services.client.MeasureClient? = null
    private var currentCallback: MeasureCallback? = null

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        super.onStartCommand(intent, flags, startId)

        if (isRunning) {
            println("[HRV Service] Already running")
            return START_STICKY
        }

        isRunning = true

        // 1. 포그라운드 서비스 시작 (Notification 필수)
        startForeground(1, createNotification())

        println("[HRV Service] Started - using Health Services API")

        // Health Services 초기화
        measureClient = HealthServices.getClient(this).measureClient

        // 2. 5분 주기 루프 시작
        lifecycleScope.launch {
            while (isRunning) {
                measureHrvOnce()

                // 4분 휴식 (총 5분 주기)
                println("[HRV Service] Sleeping for 4 minutes...")
                delay(4 * 60 * 1000L)
            }
        }

        return START_STICKY
    }

    /**
     * 1분간 심박수를 측정하여 HRV 계산
     */
    private suspend fun measureHrvOnce() {
        rrIntervals.clear()
        isMeasuring = true

        println("[HRV Service] === Starting 1-minute measurement ===")

        val callback = object : MeasureCallback {
            override fun onAvailabilityChanged(
                dataType: DeltaDataType<*, *>,
                availability: Availability
            ) {
                println("[HRV Service] Availability changed: ${availability.id}")
                // Availability 상태 로깅
                println("  → Availability: $availability")
            }

            override fun onDataReceived(data: DataPointContainer) {
                if (!isMeasuring) return

                try {
                    // HEART_RATE_BPM 데이터 포인트 가져오기
                    val heartRateData = data.getData(DataType.HEART_RATE_BPM)

                    for (dataPoint in heartRateData) {
                        // BPM 값
                        val bpm = dataPoint.value

                        // 📊 IBI (Inter-Beat Interval) 데이터 확인
                        // Galaxy Watch는 DataPoint의 추가 필드에 IBI 정보를 포함할 수 있음
                        val metadata = dataPoint.metadata

                        // IBI 데이터가 있는지 확인
                        var hasIbi = false
                        var ibiValue = 0.0

                        // 방법 1: Metadata에서 IBI 찾기
                        try {
                            // IBI는 milliseconds 단위로 제공될 수 있음
                            if (metadata.containsKey("ibi")) {
                                ibiValue = metadata.getDouble("ibi")
                                hasIbi = true
                            } else if (metadata.containsKey("rr_interval")) {
                                ibiValue = metadata.getDouble("rr_interval")
                                hasIbi = true
                            }
                        } catch (e: Exception) {
                            // Metadata에 IBI가 없음
                        }

                        // 방법 2: BPM으로부터 역산 (fallback)
                        if (!hasIbi && bpm > 0) {
                            ibiValue = 60000.0 / bpm
                            println("[HRV Service] No IBI in metadata, calculated from BPM: ${ibiValue.toInt()}ms (BPM=$bpm)")
                        } else if (hasIbi) {
                            println("[HRV Service] ✅ IBI from metadata: ${ibiValue.toInt()}ms (BPM=$bpm)")
                        }

                        // 유효한 RR Interval 범위 체크 (300ms ~ 2000ms, 즉 30-200 bpm)
                        if (ibiValue in 300.0..2000.0) {
                            rrIntervals.add(ibiValue)
                        } else {
                            println("[HRV Service] ⚠️ Invalid IBI: ${ibiValue.toInt()}ms - skipped")
                        }
                    }
                } catch (e: Exception) {
                    println("[HRV Service] Error processing data: ${e.message}")
                    e.printStackTrace()
                }
            }
        }

        currentCallback = callback

        // Health Services에 콜백 등록
        try {
            measureClient?.registerMeasureCallback(DataType.HEART_RATE_BPM, callback)
            println("[HRV Service] ✅ Health Services callback registered")
        } catch (e: Exception) {
            println("[HRV Service] ❌ Failed to register callback: ${e.message}")
            e.printStackTrace()
            isMeasuring = false
            return
        }

        // 1분간 데이터 수집
        delay(60 * 1000L)

        // 콜백 해제
        // Note: Health Services API에서 명시적 unregister가 필요하지 않을 수 있음
        // MeasureClient는 서비스가 종료될 때 자동으로 정리됨
        println("[HRV Service] Measurement complete, stopping data collection")

        isMeasuring = false
        currentCallback = null

        // HRV 계산 및 전송
        if (rrIntervals.size > 2) {
            val rmssd = calculateRmssd(rrIntervals)
            val avgHeartRate = calculateAvgHeartRate(rrIntervals)

            println("=== HRV MEASURED ===")
            println("RMSSD: ${rmssd.toInt()} ms")
            println("Avg HR: $avgHeartRate bpm")
            println("Sample count: ${rrIntervals.size}")
            println("RR Intervals: ${rrIntervals.take(5).map { it.toInt() }}... (showing first 5)")

            // 📱 폰으로 데이터 전송
            sendHrvDataToPhone(rmssd, avgHeartRate)
        } else {
            println("[HRV Service] ⚠️ Insufficient data: ${rrIntervals.size} samples")
            println("  → Make sure watch is on wrist and Health Services is available")
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        isRunning = false

        // 콜백 정리
        // Health Services는 서비스 종료 시 자동으로 정리됨
        isMeasuring = false
        currentCallback = null
        measureClient = null

        println("[HRV Service] Stopped")
    }

    // RMSSD 계산 공식
    private fun calculateRmssd(intervals: List<Double>): Double {
        if (intervals.size < 2) return 0.0

        var sumSquaredDiff = 0.0
        for (i in 0 until intervals.size - 1) {
            val diff = intervals[i + 1] - intervals[i]
            sumSquaredDiff += diff.pow(2)
        }
        return sqrt(sumSquaredDiff / (intervals.size - 1))
    }

    // 평균 심박수 계산
    private fun calculateAvgHeartRate(intervals: List<Double>): Int {
        if (intervals.isEmpty()) return 0
        val avgInterval = intervals.average()
        return (60000.0 / avgInterval).toInt()
    }

    // 📱 Wearable Data Layer API로 폰 앱에 HRV 데이터 전송
    private fun sendHrvDataToPhone(rmssd: Double, avgHeartRate: Int) {
        lifecycleScope.launch {
            try {
                val dataClient = Wearable.getDataClient(this@HrvMonitorService)

                val putDataReq = PutDataMapRequest.create("/hrv_data").apply {
                    dataMap.putDouble("rmssd", rmssd)
                    dataMap.putInt("avgHeartRate", avgHeartRate)
                    dataMap.putLong("timestamp", System.currentTimeMillis())
                    dataMap.putString("formattedTime", getCurrentTimeString())
                }.asPutDataRequest()

                val putDataTask = dataClient.putDataItem(putDataReq)
                Tasks.await(putDataTask)

                println("[HRV Service] ✅ Data sent to phone: RMSSD=${rmssd.toInt()}ms, HR=$avgHeartRate bpm")
            } catch (e: Exception) {
                println("[HRV Service] ❌ Failed to send data to phone: ${e.message}")
                e.printStackTrace()
            }
        }
    }

    private fun getCurrentTimeString(): String {
        val sdf = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault())
        return sdf.format(Date())
    }

    private fun createNotification(): Notification {
        val channelId = "hrv_service_channel"
        val channel = NotificationChannel(
            channelId,
            "HRV Monitor Service",
            NotificationManager.IMPORTANCE_LOW
        ).apply {
            description = "Measures HRV every 5 minutes using Health Services"
        }

        getSystemService(NotificationManager::class.java)?.createNotificationChannel(channel)

        return NotificationCompat.Builder(this, channelId)
            .setContentTitle("HRV 측정 중 (Health Services)")
            .setContentText("5분마다 고품질 심박변이도를 측정합니다")
            .setSmallIcon(android.R.drawable.ic_dialog_info)
            .setOngoing(true)
            .build()
    }
}

