  // [!!] 10. 비밀번호 변경 뷰 (새로 추가)
  Widget _buildPasswordEditView() {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text('비밀번호 변경', style: TextStyle(fontSize: 16, fontWeight: FontWeight.w600)),
        SizedBox(height: 16),
        _buildPasswordTextField(
          controller: _currentPasswordController,
          hintText: '현재 비밀번호',
        ),
        SizedBox(height: 12),
        _buildPasswordTextField(
          controller: _newPasswordController,
          hintText: '새 비밀번호',
        ),
        SizedBox(height: 12),
        _buildPasswordTextField(
          controller: _confirmPasswordController,
          hintText: '새 비밀번호 확인',
        ),
        SizedBox(height: 20),
        Row(
          children: [
            Expanded(
              child: OutlinedButton(
                onPressed: () {
                  // [!!] 11. '취소' 버튼 클릭 시 상태 변경
                  setState(() {
                    _isChangingPassword = false;
                  });
                  // 컨트롤러 초기화 (선택 사항)
                  _currentPasswordController.clear();
                  _newPasswordController.clear();
                  _confirmPasswordController.clear();
                },
                style: OutlinedButton.styleFrom(
                  foregroundColor: kColorTextSubtitle,
                  side: BorderSide(color: kColorEditTextBg),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),
                  padding: EdgeInsets.symmetric(vertical: 12),
                ),
                child: Text('취소'),
              ),
            ),
            SizedBox(width: 12),
            Expanded(
              child: ElevatedButton(
                onPressed: () async {
                  if (_newPasswordController.text != _confirmPasswordController.text) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('비밀번호가 일치하지 않습니다')),
                    );
                    return;
                  }

                  try {
                    final user = FirebaseAuth.instance.currentUser!;
                    final providers = user.providerData.map((e) => e.providerId).toList();

                    if (!providers.contains('password')) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('소셜 로그인 계정은 비밀번호를 변경할 수 없습니다')),
                      );
                      return;
                    }
                    final email = user.email!;

                    // ✅ 1. 재인증
                    final credential = EmailAuthProvider.credential(
                      email: email,
                      password: _currentPasswordController.text,
                    );

                    await user.reauthenticateWithCredential(credential);

                    // ✅ 2. 비밀번호 변경
                    await user.updatePassword(_newPasswordController.text);

                    if (!mounted) return;
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('비밀번호가 변경되었습니다')),
                    );

                    setState(() {
                      _isChangingPassword = false;
                    });

                    _currentPasswordController.clear();
                    _newPasswordController.clear();
                    _confirmPasswordController.clear();
                  } on FirebaseAuthException catch (e) {
                    String message;

                    if (e.code == 'wrong-password' ||
                        e.code == 'invalid-credential' ||
                        e.code == 'user-mismatch') {
                      message = '현재 비밀번호가 일치하지 않습니다';
                    } else if (e.code == 'weak-password') {
                      message = '새 비밀번호가 너무 약합니다';
                    } else if (e.code == 'requires-recent-login') {
                      message = '보안을 위해 다시 로그인해 주세요';
                    } else {
                      message = '비밀번호 변경에 실패했습니다';
                    }

                    debugPrint('FirebaseAuthException code: ${e.code}');

                    if (!mounted) return;
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(content: Text(message)),
                    );
                  }


                },

                style: ElevatedButton.styleFrom(
                  backgroundColor: kColorBtnPrimary,
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),
                  padding: EdgeInsets.symmetric(vertical: 12),
                ),
                child: Text('저장'),
              ),
            ),
          ],
        ),
      ],
    );
  }

