  Widget _buildQuestionCard({
    required int questionNumber,
    required Map<String, dynamic> question,
  }) {
    return Card(
      elevation: 2,
      color: kColorCardBg,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
      ),
      child: Padding(
        padding: const EdgeInsets.all(20.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 질문 번호와 텍스트
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  width: 28,
                  height: 28,
                  decoration: BoxDecoration(
                    color: kColorBtnPrimary,
                    borderRadius: BorderRadius.circular(14),
                  ),
                  child: Center(
                    child: Text(
                      '$questionNumber',
                      style: GoogleFonts.roboto(
                        fontSize: 14,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Text(
                    question['question'],
                    style: GoogleFonts.roboto(
                      fontSize: 16,
                      fontWeight: FontWeight.bold,
                      color: kColorTextTitle,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 16),

            // 선택지들
            ...List.generate(
              question['options'].length,
              (index) => _buildOptionTile(
                questionId: question['id'],
                optionIndex: index,
                optionText: question['options'][index]['text'],
                isSelected: _selectedAnswers[question['id']] == index,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildOptionTile({
    required String questionId,
    required int optionIndex,
    required String optionText,
    required bool isSelected,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 12.0),
      child: InkWell(
        onTap: () {
          setState(() {
            _selectedAnswers[questionId] = optionIndex;
          });
        },
        borderRadius: BorderRadius.circular(12),
        child: Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: isSelected ? kColorSelectedBg : Colors.grey[50],
            border: Border.all(
              color: isSelected ? kColorSelectedBorder : Colors.grey[300]!,
              width: isSelected ? 2 : 1,
            ),
            borderRadius: BorderRadius.circular(12),
          ),
          child: Row(
            children: [
              // 라디오 버튼 스타일 아이콘
              Container(
                width: 24,
                height: 24,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: isSelected ? kColorSelectedBorder : Colors.white,
                  border: Border.all(
                    color: isSelected ? kColorSelectedBorder : Colors.grey[400]!,
                    width: 2,
                  ),
                ),
                child: isSelected
                    ? const Icon(
                        Icons.check,
                        size: 16,
                        color: Colors.white,
                      )
                    : null,
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Text(
                  optionText,
                  style: GoogleFonts.roboto(
                    fontSize: 14,
                    color: isSelected ? kColorTextTitle : kColorTextSubtitle,
                    fontWeight: isSelected ? FontWeight.w600 : FontWeight.normal,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildSubmitButton() {
    final allAnswered = _allQuestionsAnswered();

    return SizedBox(
      width: double.infinity,
      height: 56,
      child: ElevatedButton(
        onPressed: (_isSubmitting || !allAnswered) ? null : _submitAnswers,
        style: ElevatedButton.styleFrom(
          backgroundColor: kColorBtnPrimary,
          disabledBackgroundColor: Colors.grey[300],
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(12),
          ),
          elevation: 2,
        ),
        child: _isSubmitting
            ? const SizedBox(
                width: 24,
                height: 24,
                child: CircularProgressIndicator(
                  strokeWidth: 2,
                  valueColor: AlwaysStoppedAnimation<Color>(Colors.white),
                ),
              )
            : Text(
                '분석 완료',
                style: GoogleFonts.roboto(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color: allAnswered ? Colors.white : Colors.grey[600],
                ),
              ),
      ),
    );
  }
}

