// -------------------------------------------------------------------
// 7. 새로운 공통 설문조사 페이지 (StatefulWidget)
// -------------------------------------------------------------------
class SurveyScreen extends StatefulWidget {
  final String title;
  final List<String> questions;

  const SurveyScreen({
    super.key,
    required this.title,
    required this.questions,
  });

  @override
  State<SurveyScreen> createState() => _SurveyScreenState();
}

class _SurveyScreenState extends State<SurveyScreen> {
  late List<int?> _answers;
  static const List<String> _options = [
    '전혀 그렇지 않다', // 1점
    '그렇지 않다',      // 2점
    '보통',             // 3점
    '그렇다',           // 4점
    '매우 그렇다',      // 5점
  ];

  final FirestoreService _firestoreService = FirestoreService();
  final String? _currentUserId = FirebaseAuth.instance.currentUser?.uid;
  bool _isLoading = false;

  @override
  void initState() {
    super.initState();
    _answers = List.filled(widget.questions.length, null);
  }
  // 3. 점수 평가 로직 함수
  TestResult _evaluateTest(String testTitle, int totalScore) {

    // 진단에 따라 다른 점수 기준을 적용
    switch (testTitle) {

    // '우울증' 로직
      case '우울증 자가진단':
        if (totalScore >= 10 && totalScore <= 20) {
          return TestResult(
              score: totalScore,
              title: "정상",
              description: "우울증상이 거의 없습니다.",
              advice: "현재 상태를 잘 유지하세요.",
              color: Colors.green,
          );
        } else if (totalScore >= 21 && totalScore <= 30) {
          return TestResult(
              score: totalScore,
              title: "경미한 우울",
              description: "가벼운 우울감이 있습니다.",
              advice: "기분 전환을 위한 활동을 해보세요.",
              color: Colors.blue,
          );
        } else if (totalScore >= 31 && totalScore <= 40) {
          return TestResult(
              score: totalScore,
              title: "위험한 우울",
              description: "심한 우울 증세를 보입니다.",
              advice: "심리 상담이나 전문가 도움을 고려해보세요.",
              color: Colors.yellow,
          );
        } else if (totalScore >= 41 && totalScore <= 50) {
          return TestResult(
              score: totalScore,
              title: "심각한 우울",
              description: "전문가의 상담이 필요합니다.",
              advice: "가까운 상담 센터를 방문하세요.",
              color: Colors.red,
          );
        }
        break;

    // '불안장애' 로직
      case '불안장애 자가진단':
        if (totalScore >= 10 && totalScore <= 20) {
          return TestResult(
              score: totalScore,
              title: "정상",
              description: "불안 수준이 정상 범위입니다.",
              advice: "건강한 정신 상태를 유지하고 계십니다.",
              color: Colors.green,
          );
        } else if (totalScore >= 21 && totalScore <= 30) {
          return TestResult(
              score: totalScore,
              title: "경미한 불안",
              description: "약간의 불안 증상이 있습니다.",
              advice: "이완 기법이나 명상을 통해 불안을 관리해보세요.",
              color: Colors.blue,
          );
        } else if (totalScore >= 31 && totalScore <= 40) {
          return TestResult(
              score: totalScore,
              title: "중등도 불안",
              description: "불안 증상이 의심됩니다.",
              advice: "심리 상담이나 전문가 도움을 고려해보세요.",
              color: Colors.yellow,
          );
        } else if (totalScore >= 41 && totalScore <= 50) {
          return TestResult(
              score: totalScore,
              title: "심각한 불안",
              description: "즉시 전문가 상담이 필요합니다.",
              advice: "일상생활에 지장을 줄 수 있는 불안 증상이 있습니다.",
              color: Colors.red,
          );
        }
        break;

    // '스트레스' 로직
      case '스트레스 자가진단':
        if (totalScore >= 10 && totalScore <= 20) {
          return TestResult(
              score: totalScore,
              title: "정상",
              description: "스트레스 수준이 정상 범위입니다.",
              advice: "건강한 정신 상태를 유지하고 계십니다.",
              color: Colors.green,
          );
        } else if (totalScore >= 21 && totalScore <= 30) {
          return TestResult(
              score: totalScore,
              title: "경미한 스트레스",
              description: "약간의 스트레스 증상이 있습니다.",
              advice: "가벼운 명상이나 기록 등을 통해 스트레스를 관리해보세요.",
              color: Colors.blue,
          );
        } else if (totalScore >= 31 && totalScore <= 40) {
          return TestResult(
              score: totalScore,
              title: "중등도 스트레스",
              description: "스트레스 증상이 의심됩니다.",
              advice: "심리 상담이나 전문가 도움을 고려해보세요.",
              color: Colors.yellow,
          );
        } else if (totalScore >= 41 && totalScore <= 50) {
          return TestResult(
              score: totalScore,
              title: "심각한 스트레스",
              description: "즉시 전문가 상담이 필요합니다.",
              advice: "일상생활에 지장을 줄 수 있는 스트레스 증상이 있습니다.",
              color: Colors.red,
          );
        }
        break;

    // '자살 위험성' 로직
      case '자살위험성 평가':
        if (totalScore >= 10 && totalScore <= 20) {
          return TestResult(
              score: totalScore,
              title: "정상",
              description: "자살 위험도 수준이 정상 범위입니다.",
              advice: "건강한 정신 상태를 유지하고 계십니다.",
              color: Colors.green,
          );
        } else if (totalScore >= 21 && totalScore <= 30) {
          return TestResult(
              score: totalScore,
              title: "경미한 위험 단계",
              description: "약간의 불안 증상이 있습니다.",
              advice: "이완 기법이나 명상을 통해 불안을 관리해보세요.",
              color: Colors.blue,
          );
        } else if (totalScore >= 31 && totalScore <= 40) {
          return TestResult(
              score: totalScore,
              title: "중등도 위험 상태",
              description: "불안한 자살 위험도 상태가 의심됩니다.",
              advice: "심리 상담이나 전문가 도움을 고려해보세요.",
              color: Colors.yellow,
          );
        } else if (totalScore >= 41 && totalScore <= 50) {
          return TestResult(
              score: totalScore,
              title: "심각한 위험 상태",
              description: "즉시 전문가 상담이 필요합니다.",
              advice: "일상생활에 지장을 줄 수 있는 위험도 상태입니다.",
              color: Colors.red,
          );
        }
        break;
    }

    // switch에서 해당하는 case가 없거나 오류가 발생한 경우
    return TestResult(
        score: totalScore,
        title: "결과 처리 오류",
        description: "점수 범위를 확인하거나 관리자에게 문의하세요.",
        advice: "다시 테스트해주세요.",
        color: Colors.grey,
    );
  }

  // 4. 다이얼로그 내부에 표시될 주의사항 카드
  Widget _buildDialogNoticeCard() {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12.0),
      decoration: BoxDecoration(
        color: kWarningCardBg.withOpacity(0.7), // ignore: deprecated_member_use // 기존 주의사항 카드 배경
        borderRadius: BorderRadius.circular(8.0),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(
            Icons.info_outline,
            color: kColorTextSubtitle,
            size: 18,
          ),
          const SizedBox(width: 8.0),
          Expanded(
            child: Text(
              '본 검사는 의학적 진단이 아니며, 참고용으로만 사용해 주세요. 정확한 진단은 전문의와 상담하세요.',
              style: GoogleFonts.roboto(
                fontSize: 12,
                color: kColorTextSubtitle,
                height: 1.5,
              ),
            ),
          ),
        ],
      ),
    );
  }

  // 5. _handleSubmit 함수
  void _handleSubmit() async {
    // 1. 답변 확인
    if (_answers.any((answer) => answer == null)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('모든 항목에 답변해주세요.'),
          backgroundColor: Colors.redAccent,
        ),
      );
      return;
    }

    setState(() {
      _isLoading = true;
    });

    try {
      // 2. 총점 계산 (예: 10개 문항 * 1~5점 = 10 ~ 50점 범위)
      int totalScore = _answers.fold(0, (sum, score) => sum + (score ?? 0));

      // 3. 결과 텍스트 생성 (UI 표시용)
      TestResult result = _evaluateTest(widget.title, totalScore);

      // 4. Firestore 저장 호출
      if (_currentUserId != null) {
        // Service가 내부적으로 점수 환산(0~100) 및 종합 점수 업데이트를 수행합니다.
        await _firestoreService.updateMentalHealthScore(
            _currentUserId!,
            widget.title,
            totalScore // 원본 점수(10~50)를 넘김
        );
        print('✅ [Diagnosis] ${widget.title} 점수 저장 완료 및 종합 점수 업데이트 트리거됨');
      } else {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('로그인이 필요합니다. 점수는 저장되지 않습니다.')),
        );
      }

      // 5. 다이얼로그 표시 (기존 코드 유지)
      showDialog(
        context: context,
        barrierDismissible: false,
        builder: (context) => AlertDialog(
          // ... (기존 다이얼로그 코드 그대로 유지) ...
          title: Text(widget.title),
          content: SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  result.title,
                  style: GoogleFonts.roboto(
                    fontSize: 20,
                    fontWeight: FontWeight.bold,
                    color: result.color,
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  '총점: ${result.score}점',
                  style: GoogleFonts.roboto(
                    fontSize: 14,
                    color: kColorTextSubtitle,
                  ),
                ),
                const Divider(height: 24),
                Text(result.description, style: GoogleFonts.roboto(fontSize: 14, color: kColorTextLabel, height: 1.5)),
                const SizedBox(height: 12),
                Text(result.advice, style: GoogleFonts.roboto(fontSize: 14, color: kColorTextLabel, height: 1.5)),
                const SizedBox(height: 20),
                _buildDialogNoticeCard(),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(context); // 다이얼로그 닫기
                Navigator.pop(context); // 목록 화면으로 돌아가기
              },
              child: const Text('확인'),
            ),
          ],
        ),
      );
    } catch (e) {
      print('❌ [Diagnosis] 저장 중 오류 발생: $e');
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('저장 중 오류가 발생했습니다: $e')),
      );
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.title),
        backgroundColor: kColorCardBg,
        foregroundColor: kColorTextTitle,
        elevation: 1,
        leading: IconButton(
          icon: Icon(
            Icons.arrow_back,
            color: kColorTextTitle,
            size: 20,
          ),
          onPressed: () => Navigator.pop(context),
        ),
      ),
      backgroundColor: kPageBackground,
      body: Column(
        children: [
          Expanded(
            child: ListView.builder(
              padding: const EdgeInsets.all(16.0),
              itemCount: widget.questions.length,
              itemBuilder: (context, index) {
                return SurveyQuestionItem(
                  questionNumber: index + 1,
                  questionText: widget.questions[index],
                  options: _options,
                  selectedValue: _answers[index],
                  onChanged: (value) {
                    setState(() {
                      _answers[index] = value;
                    });
                  },
                );
              },
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(24.0),
            child: ElevatedButton(
              style: ElevatedButton.styleFrom(
                backgroundColor: kColorBtnPrimary,
                foregroundColor: Colors.white,
                minimumSize: const Size(double.infinity, 50),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
              onPressed: _isLoading ? null : _handleSubmit, // [!!] 수정된 handleSubmit 함수가 호출됨
              child: _isLoading
                  ? const SizedBox(
                height: 24.0,
                width: 24.0,
                child: CircularProgressIndicator(
                  color: Colors.white,
                  strokeWidth: 2.0,
                ),
              )
                  : Text(
                '결과 보기',
                style: GoogleFonts.roboto(
                    fontSize: 16, fontWeight: FontWeight.bold),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

// -------------------------------------------------------------------
// 8. 개별 질문 항목 위젯 (StatelessWidget)
// -------------------------------------------------------------------
class SurveyQuestionItem extends StatelessWidget {
  final int questionNumber;
  final String questionText;
  final List<String> options;
  final int? selectedValue;
  final ValueChanged<int?> onChanged;

  const SurveyQuestionItem({
    super.key,
    required this.questionNumber,
    required this.questionText,
    required this.options,
    required this.selectedValue,
    required this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    return Card(
      margin: const EdgeInsets.symmetric(vertical: 8.0),
      elevation: 1,
      color: kColorCardBg,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              '$questionNumber. $questionText',
              style: GoogleFonts.roboto(
                fontSize: 16,
                fontWeight: FontWeight.w500,
                color: kColorTextTitle,
              ),
            ),
            const SizedBox(height: 12.0),
            RadioGroup<int>(
              groupValue: selectedValue,
              onChanged: onChanged,
              child: Column(
                children: List.generate(options.length, (index) {
                  final value = index + 1;
                  final optionText = options[index];

                  return RadioListTile<int>(
                    title: Text(
                      optionText,
                      style: GoogleFonts.roboto(
                        fontSize: 14,
                        color: kColorTextLabel,
                      ),
                    ),
                    value: value,
                    activeColor: kColorBtnPrimary,
                    contentPadding: EdgeInsets.zero,
                  );
                }),
              ),
            ),
          ],
        ),
      ),
    );
  }
}
